import itertools
import threading

class RoundRobin:
    def __init__(self, endpoints):
        self._lock = threading.Lock()
        self._endpoints = list(endpoints)
        self._cursor = 0

    def set_healthy(self, healthy):
        # Membership is the only mutable state. Changing N remaps traffic.
        with self._lock:
            self._endpoints = list(healthy)

    def pick(self):
        with self._lock:
            if not self._endpoints:
                raise RuntimeError("no healthy backends")
            idx = self._cursor % len(self._endpoints)
            self._cursor = (self._cursor + 1) % (1 << 62)  # avoid unbounded growth
            return self._endpoints[idx]

# Weighted variant: expand the ring by static capacity.
# Trade-off: fixes static heterogeneity, goes stale when capacity shifts.
class WeightedRoundRobin:
    def __init__(self, weighted):
        ring = []
        for ep, w in weighted:
            ring.extend([ep] * max(1, w))
        self._ring = itertools.cycle(ring)
        self._lock = threading.Lock()

    def pick(self):
        with self._lock:
            return next(self._ring)
